<?php
namespace App\Http\Controllers\CRM; use App\Http\Controllers\Controller; use App\Models\Promotion; use Illuminate\Http\Request;
class PromotionController extends Controller {public function index(){return view('crm.promotions',['promotions'=>Promotion::where('property_id',auth()->user()->property_id)->latest()->paginate(30)]);} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:150','code'=>'nullable|string|max:50','type'=>'required|in:percentage,fixed','value'=>'required|numeric|min:0','minimum_spend'=>'nullable|numeric|min:0','maximum_discount'=>'nullable|numeric|min:0','starts_at'=>'required|date','ends_at'=>'required|date|after:starts_at','usage_limit'=>'nullable|integer|min:1','per_guest_limit'=>'nullable|integer|min:1']);$d+=['property_id'=>auth()->user()->property_id,'is_active'=>true];Promotion::create($d);return back()->with('success','Promotion created.');} public function toggle(Promotion $promotion){abort_unless($promotion->property_id===auth()->user()->property_id,403);$promotion->update(['is_active'=>!$promotion->is_active]);return back()->with('success','Promotion status updated.');}}
